<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#0b090d">
<title>Steaming Bowl — Vegan Ramen</title>
<style>
  :root{
    --amber: #ffb45e;
    --amber-hot: #ff9a3c;
  }
  *, *::before, *::after{ margin:0; padding:0; box-sizing:border-box; }
  html, body{ height:100%; }
  body{
    min-height:100vh;
    overflow:hidden;
    background:
      radial-gradient(130% 95% at 50% 12%, #211713 0%, #140f12 42%, #0a080c 78%, #060509 100%);
    font-family: system-ui, sans-serif;
  }
  #scene{
    position:fixed; inset:0; overflow:hidden;
    display:flex; align-items:center; justify-content:center;
  }

  /* ---------- ambient warmth ---------- */
  .lamp-glow{
    position:absolute; left:50%; top:-32vmax; width:150vmax; height:110vmax;
    transform:translateX(-50%);
    background:radial-gradient(50% 50% at 50% 0%,
      rgba(255,186,102,.34) 0%,
      rgba(255,150,70,.13) 34%,
      rgba(255,140,60,.045) 55%,
      transparent 72%);
    animation: glowFlicker 7s ease-in-out infinite;
    pointer-events:none; z-index:1;
  }
  @keyframes glowFlicker{
    0%,100%{ opacity:.86; }
    22%{ opacity:1; }
    41%{ opacity:.78; }
    63%{ opacity:.96; }
    81%{ opacity:.84; }
  }
  .table-pool{
    position:absolute; left:0; right:0; bottom:0; height:34%;
    background:
      radial-gradient(58% 92% at 50% 6%, rgba(255,158,72,.17) 0%, rgba(150,84,40,.06) 46%, transparent 72%),
      linear-gradient(to bottom, rgba(22,15,13,0) 0%, #17100e 34%, #0c090a 100%);
    z-index:1; pointer-events:none;
  }
  .table-pool::before{
    content:""; position:absolute; left:0; right:0; top:0; height:1px;
    background:linear-gradient(to right, transparent, rgba(255,196,140,.13) 30%, rgba(255,196,140,.13) 70%, transparent);
  }
  .halo{
    position:absolute; left:50%; bottom:24%; width:min(92vw,64vmin); height:min(46vw,32vmin);
    transform:translateX(-50%);
    background:radial-gradient(50% 50% at 50% 50%, rgba(255,166,74,.24) 0%, rgba(255,140,60,.08) 48%, transparent 74%);
    filter:blur(10px);
    animation: breathe 5.5s ease-in-out infinite;
    pointer-events:none; z-index:2;
  }
  @keyframes breathe{
    0%,100%{ opacity:.6; transform:translateX(-50%) scale(.97); }
    50%{ opacity:1; transform:translateX(-50%) scale(1.03); }
  }

  /* ---------- the bowl ---------- */
  .bowl{
    position:relative; z-index:3;
    width:min(88vw, calc(74vh * 1.488));
    max-width:700px;
    translate:0 4vh;
    will-change:transform;
    transform-style:preserve-3d;
  }
  .bowl svg{ display:block; width:100%; height:auto; overflow:visible; }
  .bowl svg .rim-light{ animation: rimFlicker 6s ease-in-out infinite; }
  @keyframes rimFlicker{ 0%,100%{opacity:.30} 30%{opacity:.42} 55%{opacity:.26} 78%{opacity:.38} }

  .soupLight{ animation: soupPulse 4.6s ease-in-out infinite; }
  @keyframes soupPulse{ 0%,100%{opacity:.20} 50%{opacity:.34} }

  .ripples ellipse{
    fill:none; stroke:#ffe6ba; stroke-width:2;
    opacity:0;
    transform-box:fill-box; transform-origin:center;
    animation: rippleOut 3.4s cubic-bezier(.2,.6,.35,1) infinite;
  }
  .ripples ellipse:nth-child(2){ animation-delay:1.15s; }
  .ripples ellipse:nth-child(3){ animation-delay:2.3s; }
  @keyframes rippleOut{
    0%{ transform:scale(.32); opacity:0; }
    14%{ opacity:.55; }
    100%{ transform:scale(1.18); opacity:0; }
  }
  .wisps{ display:none; }

  /* ---------- atmosphere layers ---------- */
  .light{
    position:fixed; left:0; top:0; z-index:4;
    width:560px; height:560px; border-radius:50%;
    background:radial-gradient(circle,
      rgba(255,199,128,.30) 0%,
      rgba(255,160,74,.12) 42%,
      transparent 68%);
    mix-blend-mode:screen;
    pointer-events:none;
    will-change:transform, opacity;
  }
  #fx{
    position:fixed; inset:0; z-index:5;
    width:100%; height:100%;
    mix-blend-mode:screen;
    pointer-events:none;
  }
  .vignette{
    position:fixed; inset:0; z-index:6; pointer-events:none;
    background:radial-gradient(125% 100% at 50% 44%, transparent 42%, rgba(4,3,6,.52) 82%, rgba(2,2,3,.78) 100%);
  }

  @media (prefers-reduced-motion: reduce){
    *, *::before, *::after{
      animation-duration:.001s !important;
      animation-iteration-count:1 !important;
      transition:none !important;
    }
    .light{ display:none; }
    .wisps{ display:block; }
    .wisps path{ opacity:.42; }
    .ripples ellipse{ opacity:.22; animation:none; }
    .soupLight{ opacity:.3; animation:none; }
    .rim-light{ opacity:.3; animation:none; }
  }
  @media (max-width:560px){
    .halo{ bottom:26%; }
    .bowl{ translate:0 3vh; }
  }
</style>
</head>
<body>
