<script>
(function(){
  "use strict";
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  var scene   = document.getElementById("scene");
  var bowlEl  = document.getElementById("bowl");
  var lightEl = document.getElementById("light");
  var ripples = document.getElementById("ripples");
  var canvas  = document.getElementById("fx");
  var ctx     = canvas.getContext("2d");

  var W = window.innerWidth, H = window.innerHeight;
  var dpr = Math.min(window.devicePixelRatio || 1, 2);

  function resize(){
    W = window.innerWidth; H = window.innerHeight;
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width  = Math.round(W * dpr);
    canvas.height = Math.round(H * dpr);
    canvas.style.width  = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  resize();
  window.addEventListener("resize", resize);

  /* ---------- interaction state ---------- */
  var mx = W * 0.5, my = H * 0.40;
  var tmx = mx, tmy = my;
  var lastTarget = performance.now();
  var prevTx = tmx, prevTy = tmy;
  var boost = 0;

  function point(e){
    tmx = e.clientX; tmy = e.clientY;
    lastTarget = performance.now();
  }
  window.addEventListener("pointermove", point, { passive: true });
  window.addEventListener("pointerdown", point, { passive: true });

  /* ---------- steam particles ---------- */
  var particles = [];
  var dust = [];
  for (var i = 0; i < 22; i++){
    dust.push({
      x: Math.random() * W,
      y: H * 0.15 + Math.random() * H * 0.7,
      r: 1 + Math.random() * 1.8,
      phase: Math.random() * Math.PI * 2,
      vx: -0.03 + Math.random() * 0.06,
      vy: -0.05 - Math.random() * 0.08
    });
  }

  function measure(){
    var r = bowlEl.getBoundingClientRect();
    return {
      cx: r.left + r.width * 0.5,
      cy: r.top + r.height * (170 / 430),
      rx: r.width * (176 / 640)
    };
  }

  function spawn(m){
    var a = Math.random() * Math.PI * 2;
    var rr = Math.sqrt(Math.random()) * 0.86;
    var x = m.cx + Math.cos(a) * m.rx * rr;
    var y = m.cy + Math.sin(a) * (m.rx * 0.24) * rr - 4;
    particles.push({
      x: x, y: y,
      vy: -(0.42 + Math.random() * 0.5),
      r: 13 + Math.random() * 16,
      life: 0,
      maxLife: 200 + Math.random() * 110,
      phase: Math.random() * Math.PI * 2,
      sway: 0.35 + Math.random() * 0.5,
      alphaMax: 0.10 + Math.random() * 0.08
    });
  }

  var lastT = 0, running = true;
  document.addEventListener("visibilitychange", function(){ running = !document.hidden; });

  function frame(t){
    if (!running) { requestAnimationFrame(frame); return; }
    var dt = Math.min(3.4, (t - lastT) / 16.7 || 1);
    lastT = t;

    /* idle → slow autonomous drift of the light */
    if (t - lastTarget > 2600){
      tmx = W * 0.5 + Math.sin(t * 0.00033) * W * 0.20;
      tmy = H * 0.40 + Math.cos(t * 0.00047) * H * 0.09;
    }
    var spdx = tmx - prevTx, spdy = tmy - prevTy;
    prevTx = tmx; prevTy = tmy;
    var speed = Math.sqrt(spdx * spdx + spdy * spdy);
    boost += (Math.min(1, speed / 13) - boost) * 0.10;

    mx += (tmx - mx) * 0.065;
    my += (tmy - my) * 0.065;

    /* light follows the pointer */
    var m = measure();
    var dBowl = Math.hypot(mx - m.cx, my - m.cy);
    var prox = Math.max(0, 1 - dBowl / (Math.min(W, H) * 0.85));
    var scale = (0.85 + prox * 0.55) * (1 + Math.sin(t * 0.0019) * 0.05);
    var flicker = 0.82 + 0.10 * Math.sin(t * 0.0031) + 0.06 * Math.sin(t * 0.0117 + 1.7);
    lightEl.style.opacity = (flicker * (0.75 + prox * 0.45)).toFixed(3);
    lightEl.style.transform = "translate3d(" + (mx - 280) + "px," + (my - 280) + "px,0) scale(" + scale.toFixed(3) + ")";

    /* bowl tilts gently toward the pointer */
    var bob = Math.sin(t * 0.0011) * 3;
    var ry = (mx / W - 0.5) * 7.5;
    var rx = (my / H - 0.45) * -6;
    bowlEl.style.transform = "perspective(1100px) rotateX(" + rx.toFixed(2) + "deg) rotateY(" + ry.toFixed(2) + "deg) translateY(" + bob.toFixed(1) + "px)";

    /* ripples surge when the pointer swipes across the bowl */
    ripples.style.opacity = (0.35 + boost * 0.65).toFixed(2);

    /* ------- canvas: steam + dust ------- */
    ctx.clearRect(0, 0, W, H);

    if (particles.length < 46 && Math.random() < 0.20) spawn(m);

    for (var i = particles.length - 1; i >= 0; i--){
      var p = particles[i];
      p.life += dt;
      p.y += p.vy * dt;
      p.x += (Math.sin(t * 0.0016 + p.phase) * p.sway * 0.6 + Math.sin(t * 0.0007 + p.phase * 2) * 0.25) * dt;

      var dx = p.x - mx, dy = p.y - my;
      var d = Math.sqrt(dx * dx + dy * dy);
      if (d < 160 && d > 1){
        var f = (160 - d) / 160 * 0.9;
        p.x += dx / d * f * dt;
        p.vy -= f * 0.006 * dt;
      }

      p.r += 0.16 * dt;
      var k = p.life / p.maxLife;
      if (k >= 1 || p.y < -60){ particles.splice(i, 1); continue; }

      var alpha = Math.sin(Math.min(1, k) * Math.PI) * p.alphaMax;
      var g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r);
      g.addColorStop(0, "rgba(255,240,224," + alpha.toFixed(3) + ")");
      g.addColorStop(0.55, "rgba(255,232,212," + (alpha * 0.45).toFixed(3) + ")");
      g.addColorStop(1, "rgba(255,226,204,0)");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, 6.2832);
      ctx.fill();
    }

    for (var j = 0; j < dust.length; j++){
      var d2 = dust[j];
      d2.x += d2.vx * dt; d2.y += d2.vy * dt;
      if (d2.y < -10){ d2.y = H + 10; d2.x = Math.random() * W; }
      if (d2.x < -10) d2.x = W + 10;
      if (d2.x > W + 10) d2.x = -10;
      var tw = 0.05 + 0.06 * (0.5 + 0.5 * Math.sin(t * 0.0018 + d2.phase));
      ctx.fillStyle = "rgba(255,214,170," + tw.toFixed(3) + ")";
      ctx.beginPath();
      ctx.arc(d2.x, d2.y, d2.r, 0, 6.2832);
      ctx.fill();
    }

    requestAnimationFrame(frame);
  }

